tools.example:
disp(serialportlist("available"))
s = serialport("COM3", 115200, "Timeout", 5);
configureTerminator(s, "LF");
flush(s);
writeline(s, "*IDN?");
id = readline(s);
fprintf('Instrument: %s\n', id);
clear s

ports = serialportlist("available");
if isempty(ports)
    error('No serial ports available');
end
fprintf('Found: %s\n', strjoin(ports, ', '));
s = serialport(ports(1), 9600);

t = tcpclient("192.168.1.50", 5025, "Timeout", 5, "EnableTransferDelay", false);
configureTerminator(t, "LF");
writeline(t, "*IDN?");
fprintf('%s\n', readline(t));
writeline(t, "MEAS:VOLT:DC?");
v = str2double(readline(t));
clear t

server = tcpserver("0.0.0.0", 8080, "Timeout", 30);
configureCallback(server, "terminator", @handleLine);
fprintf('Listening on port %d...\n', server.ServerPort);
function handleLine(src, ~)
    msg = readline(src);
    fprintf('Received: %s\n', msg);
    writeline(src, "ACK");
end

u = udpport("LocalPort", 5005, "EnableBroadcast", true, "Timeout", 2);
write(u, single([1.5 2.5 3.5]), "single", "192.168.1.255", 5005);
data = read(u, 3, "single");
fprintf('Received: %s\n', mat2str(data));
clear u

devs = visadevlist;
disp(devs)
v = visadev(devs.ResourceName(1));
v.Timeout = 10;
fprintf('ID: %s\n', writeread(v, "*IDN?"));
writeline(v, ":WAV:FORM BYTE");
writeline(v, ":WAV:DATA?");
wave = readbinblock(v, "uint8");
clear v

devices = visadevlist;
if isempty(devices)
    error('No VISA instruments found. Check the VISA installation.');
end
disp(devices(:, {'ResourceName','Vendor','Model','Type'}))
scope = visadev(devices.ResourceName(devices.Model == "DSO-X 2024A"));

s = serialport("COM4", 115200);
configureTerminator(s, "CR/LF");
writeline(s, "SYST:REM");
writeline(s, "VOLT 5.0");
writeline(s, "OUTP ON");
pause(0.5);
writeline(s, "MEAS:CURR?");
current = str2double(readline(s));

s = serialport("COM4", 9600, "Timeout", 3);
configureTerminator(s, "LF");
writeline(s, "READ?");
response = readline(s);
if ismissing(response)
    warning('Timed out waiting for the instrument');
else
    value = str2double(response);
end

t = tcpclient("192.168.0.10", 4000);
t.ByteOrder = "big-endian";
header = uint8([hex2dec('AA') hex2dec('55') 4 0]);
write(t, header, "uint8");
write(t, single([1.0 2.0 3.0 4.0]), "single");
reply = read(t, 2, "uint8");

s = serialport("COM5", 921600, "Timeout", 2);
flush(s);
write(s, uint8(hex2dec('01')), "uint8");     % request a sample block
nSamples = 1024;
raw = read(s, nSamples, "int16");
volts = double(raw) * 3.3 / 32768;
plot(volts)
fprintf('%d bytes still buffered\n', s.NumBytesAvailable);

v = visadev("GPIB0::22::INSTR");
fprintf('%s\n', writeread(v, "*IDN?"));
writeline(v, "CONF:VOLT:DC 10,0.001");
reading = str2double(writeread(v, "READ?"));
fprintf('DC voltage: %.6f V\n', reading);
errs = writeread(v, "SYST:ERR?");
clear v

s = serialport("COM3", 115200);
configureTerminator(s, "CR/LF");            % same both ways
configureTerminator(s, "LF", "CR/LF");      % read LF, write CR/LF
writeline(s, "*IDN?");
disp(readline(s))

m = modbus('tcpip', '192.168.1.100', 502, 'Timeout', 5);
temps = read(m, 'holdingregs', 100, 4, 1);
fprintf('Temperatures: %s\n', mat2str(temps/10));
write(m, 'coils', 10, [1 0 1], 1);
status = read(m, 'inputs', 0, 8, 1);
clear m

dq = daq("ni");
dq.Rate = 10000;
addinput(dq, "Dev1", "ai0", "Voltage");
addinput(dq, "Dev1", "ai1", "Voltage");
data = read(dq, seconds(2), "OutputFormat", "Matrix");
plot((0:size(data,1)-1)/dq.Rate, data)
xlabel('Time (s)'); ylabel('Volts')

devices = daqlist("ni");
disp(devices)
if isempty(devices)
    error('No NI devices detected');
end
info = devices.DeviceInfo(1);
disp(info.Subsystems(1))
dq = daq("ni");
addinput(dq, devices.DeviceID(1), "ai0", "Voltage");

dq = daq("ni");
ch = addinput(dq, "Dev1", "ai0", "Voltage");
ch.TerminalConfig = "Differential";
ch.Range = [-5 5];
tc = addinput(dq, "Dev1", "ai1", "Thermocouple");
tc.ThermocoupleType = "K";
dq.Rate = 1000;
data = read(dq, seconds(1));

dq = daq("ni");
dq.Rate = 10000;
addoutput(dq, "Dev1", "ao0", "Voltage");
addinput(dq, "Dev1", "ai0", "Voltage");
t = (0:1/dq.Rate:1-1/dq.Rate)';
stimulus = 2.5 * sin(2*pi*50*t);
response = readwrite(dq, stimulus, "OutputFormat", "Matrix");
plot(t, stimulus, t, response)

dq = daq("ni");
dq.Rate = 50000;
addoutput(dq, "Dev1", "ao0", "Voltage");
addinput(dq, "Dev1", "ai0", "Voltage");
t = (0:1/dq.Rate:0.5-1/dq.Rate)';
sweep = chirp(t, 100, 0.5, 10000);
resp = readwrite(dq, sweep, "OutputFormat", "Matrix");
[txy, f] = tfestimate(sweep, resp, hann(2048), 1024, 4096, dq.Rate);
semilogx(f, 20*log10(abs(txy)))

dq = daq("ni");
dq.Rate = 20000;
addinput(dq, "Dev1", "ai0", "Voltage");
dq.ScansAvailableFcnCount = 2000;
buffer = [];
dq.ScansAvailableFcn = @(src, evt) assignin('base', 'buffer', ...
    [evalin('base','buffer'); read(src, src.ScansAvailableFcnCount, "OutputFormat", "Matrix")]);
start(dq, "Continuous");
pause(10);
stop(dq);

start(dq, "Continuous");
tic
while toc < 30
    pause(0.1);
    if someStopCondition
        break
    end
end
stop(dq);
remaining = read(dq, "all", "OutputFormat", "Matrix");
flush(dq);

a = arduino('COM4', 'Uno', 'Libraries', {'I2C','Servo'});
fprintf('Board: %s, available pins: %s\n', a.Board, strjoin(a.AvailablePins, ' '));
configurePin(a, 'D13', 'DigitalOutput');
for k = 1:5
    writeDigitalPin(a, 'D13', 1); pause(0.5);
    writeDigitalPin(a, 'D13', 0); pause(0.5);
end
v = readVoltage(a, 'A0');
clear a

a = arduino();
N = 200;
v = zeros(N, 1);
t = zeros(N, 1);
tic
for k = 1:N
    v(k) = readVoltage(a, 'A0');
    t(k) = toc;
    pause(0.05);
end
plot(t, v); xlabel('Time (s)'); ylabel('Volts')
tempC = (v - 0.5) * 100;      % TMP36 sensor conversion

a = arduino();
configurePin(a, 'D7', 'DigitalOutput');
for k = 1:10
    writeDigitalPin(a, 'D7', mod(k, 2));
    pause(0.2);
end
writePWMDutyCycle(a, 'D9', 0.35);     % 35% duty cycle on a PWM pin
state = readDigitalPin(a, 'D2');

rpi = raspi('192.168.1.42', 'pi', 'raspberry');
fprintf('Board: %s, available pins: %s\n', rpi.BoardName, mat2str(rpi.AvailableDigitalPins));
configurePin(rpi, 17, 'DigitalOutput');
for k = 1:6
    writeDigitalPin(rpi, 17, mod(k, 2));
    pause(0.5);
end
temp = system(rpi, 'vcgencmd measure_temp');
fprintf('CPU %s', temp);
clear rpi
